const event = $json.body ?? $json;
const message = event.message ?? {};
const action = event.action ?? event.common?.invokedFunction ?? {};
const parameters = Object.fromEntries((action.parameters ?? []).map((p) => [p.key, p.value]));
const threadName = message.thread?.name ?? event.thread?.name ?? `${event.space?.name ?? 'unknown'}:${message.name ?? Date.now()}`;
const messages = event.threadMessages ?? event.messages ?? [];
return [{ json: {
  eventType: event.type ?? (event.action ? 'CARD_CLICK' : 'MESSAGE'),
  actionName: action.actionMethodName ?? action.function ?? parameters.action ?? null,
  actionToken: parameters.confirmationToken ?? parameters.token ?? null,
  threadName,
  spaceName: event.space?.name ?? null,
  sender: event.user?.displayName ?? message.sender?.displayName ?? null,
  text: String(message.argumentText ?? message.text ?? event.text ?? '').trim(),
  threadMessages: messages.slice(-20),
  sourceUrl: message.name ? `https://chat.google.com/room/${encodeURIComponent(event.space?.name ?? '')}/${encodeURIComponent(message.name)}` : null,
} }];

const normalized = $('Normalize Q&A Event').item.json;
const messages = Array.isArray($json.messages) ? $json.messages.slice(-20) : [];
return [{ json: { ...normalized, threadMessages: messages } }];

const normalized = $('Normalize Q&A Event').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? $json.message?.content ?? '{}';
let answer;
try {
  answer = JSON.parse(String(raw).replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim());
} catch (error) {
  answer = { answer: 'I could not safely parse the research response.', confidence: 'low', evidence: [], status: 'needs_clarification', followUpQuestion: 'Please retry or ask a human to inspect the bot execution.', issueDraft: null };
}
const staticData = $getWorkflowStaticData('global');
staticData.threads = staticData.threads || {};
const prior = staticData.threads[normalized.threadName] || {};
const confirmed = normalized.actionName === 'confirm_issue'
  && prior.phase === 'offered'
  && prior.confirmationToken === normalized.actionToken
  && prior.issueDraft;
if (confirmed) {
  delete staticData.threads[normalized.threadName];
  return [{ json: { ...normalized, route: 'create', issuePayload: { repo: 'trimble-oss/modus-wc-2.0', title: prior.issueDraft.title, summary: prior.issueDraft.summary, type: prior.issueDraft.type, components: prior.issueDraft.components || [], labels: prior.issueDraft.labels || ['needs-scaffolding'], source: { kind: 'google-chat', url: normalized.sourceUrl, threadName: normalized.threadName }, rawConversation: normalized.threadMessages || [], contextEvidence: prior.evidence || [], idempotencyKey: `qa:${normalized.threadName}:${prior.confirmationToken}`, autoApprove: false } } }];
}
if (answer.status === 'work_implied' && answer.issueDraft) {
  const confirmationToken = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
  staticData.threads[normalized.threadName] = { phase: 'offered', updatedAt: Date.now(), issueDraft: answer.issueDraft, evidence: answer.evidence || [], confirmationToken };
  return [{ json: { ...normalized, route: 'reply', answer, confirmationToken } }];
}
if (answer.status === 'needs_clarification') {
  staticData.threads[normalized.threadName] = { phase: 'clarifying', updatedAt: Date.now(), evidence: answer.evidence || [] };
}
return [{ json: { ...normalized, route: 'reply', answer, confirmationToken: null } }];

const answer = $json.answer || {};
const evidence = (answer.evidence || []).map((item) => `${item.claim} (<a href=\"${item.source}\">source</a>)`).join('<br>');
const widgets = [{ textParagraph: { text: answer.answer || 'I could not find an answer in the shared context.' } }];
if (answer.followUpQuestion) widgets.push({ textParagraph: { text: `<b>Question:</b> ${answer.followUpQuestion}` } });
if (evidence) widgets.push({ textParagraph: { text: `<b>Evidence</b><br>${evidence}` } });
if (answer.status === 'work_implied' && answer.issueDraft) {
  widgets.push({ textParagraph: { text: `<b>Possible work:</b> ${answer.issueDraft.title}<br>${answer.issueDraft.summary || ''}` } });
  widgets.push({ buttonList: { buttons: [
    { text: 'Draft an issue', onClick: { action: { actionMethodName: 'confirm_issue', parameters: [{ key: 'confirmationToken', value: $json.confirmationToken }] } } },
    { text: 'Not now', onClick: { action: { actionMethodName: 'discard_issue' } } },
  ] } });
}
return [{ json: { chatResponse: { cardsV2: [{ cardId: `qa-${Date.now()}`, card: { header: { title: 'Modus Q&A', subtitle: answer.status || 'answer' }, sections: [{ widgets }] } }] } } }];
